class IChingDB {
  static getAllHexagrams() {
    return ICHING_DATA;
  }

  static getByNumber(num) {
    const n = parseInt(num, 10);
    return ICHING_DATA.find(h => h.number === n) || null;
  }

  static getByLines(lines) {
    if (!Array.isArray(lines) || lines.length !== 6) return null;
    return ICHING_DATA.find(h => {
      return h.binaryLines.every((bit, idx) => bit === lines[idx]);
    }) || null;
  }

  static search(keyword) {
    if (!keyword) return [];
    const kw = keyword.trim().toLowerCase();
    return ICHING_DATA.filter(h => {
      return h.nameZh.includes(kw) ||
             h.nameEn.toLowerCase().includes(kw) ||
             h.judgmentZh.includes(kw) ||
             h.judgmentEn.toLowerCase().includes(kw) ||
             (h.modernInterpretation && h.modernInterpretation.philosophyZh && h.modernInterpretation.philosophyZh.includes(kw));
    });
  }
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { ICHING_DATA, IChingDB };
}
if (typeof window !== 'undefined') {
  window.ICHING_DATA = ICHING_DATA;
  window.IChingDB = IChingDB;
}
